head.script:
//
/* Smart Choice loader: يجلب أحدث smart-choice.js من GitHub (كاش 5 دقائق) بدل الاعتماد على كاش CDN الطويل. */
(function () {
  var raw = "https://raw.githubusercontent.com/tahattaha41/Smart-Choice/main/assets/js/smart-choice.js";
  var cdn = "https://cdn.jsdelivr.net/gh/tahattaha41/Smart-Choice@main/assets/js/smart-choice.js";
  function viaCdn() { var s = document.createElement("script"); s.src = cdn + "?v=" + Math.floor(Date.now() / 600000); document.head.appendChild(s); }
  try {
    fetch(raw + "?t=" + Math.floor(Date.now() / 300000), { credentials: "omit" })
      .then(function (r) { if (!r.ok) { throw new Error(r.status); } return r.text(); })
      .then(function (code) { var s = document.createElement("script"); s.textContent = code; document.head.appendChild(s); })
      .catch(viaCdn);
  } catch (e) { viaCdn(); }
})();
//

window.dataLayer = window.dataLayer || [];
function gtag(){dataLayer.push(arguments);}
gtag('js', new Date());
gtag('config', 'G-BRZP957SQ4');

head.b:skin:
:root{--navy:#102b50;--blue:#176b87;--ink:#182338;--muted:#607086;--line:#e3eaf0;--paper:#f6f9fc;--white:#fff}
    *{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:system-ui,-apple-system,"Segoe UI",Tahoma,Arial,sans-serif;line-height:1.8}
    a{color:var(--blue);text-decoration:none}a:hover{text-decoration:underline}.sc-wrap{width:min(1120px,calc(100% - 32px));margin:auto}
    .sc-top{background:var(--navy);color:#dceafa;font-size:13px;padding:6px 0}.sc-head{background:#fff;border-bottom:1px solid var(--line)}
    .sc-headin{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:18px 0;flex-wrap:wrap}
    .sc-brand{font-size:25px;font-weight:850;color:var(--navy);letter-spacing:-.5px}.sc-brand span{color:var(--blue)}
    .sc-nav{display:flex;gap:8px;flex-wrap:wrap}.sc-nav a{padding:8px 12px;border-radius:10px;color:var(--ink);font-weight:650}.sc-nav a:hover{background:#edf5f8;text-decoration:none}
    .sc-main{min-height:55vh;padding:26px 0 52px}.sc-hero{background:linear-gradient(130deg,var(--navy),var(--blue));border-radius:24px;color:white;padding:clamp(24px,5vw,48px);margin:4px 0 26px}
    .sc-hero h1{font-size:clamp(28px,5vw,44px);line-height:1.25;margin:0 0 12px}.sc-hero p{max-width:680px;color:#e4f1fa;margin:0}
    .sc-sectiontitle{font-size:24px;margin:28px 0 14px}.sc-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}
    .sc-card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:20px;box-shadow:0 5px 20px #102b5008}.sc-card h3{margin:0 0 7px;font-size:18px}.sc-card p{color:var(--muted);margin:0}
    .sc-btn{display:inline-block;background:var(--blue);color:#fff;padding:10px 16px;border-radius:11px;font-weight:700;margin-top:14px}.sc-btn:hover{background:var(--navy);text-decoration:none}
    .blog-posts{display:grid;gap:16px}.date-header{display:none}.post-outer,.post{background:white;border:1px solid var(--line);border-radius:18px;padding:clamp(16px,3vw,28px);margin:0 0 16px}.post-title{font-size:25px;line-height:1.4}.post-body{overflow-wrap:anywhere}.post-body img{max-width:100%;height:auto;border-radius:12px}
    .sc-footer{background:var(--navy);color:#dceafa;padding:28px 0;margin-top:30px}.sc-footer a{color:#fff}.sc-footlinks{display:flex;gap:16px;flex-wrap:wrap;margin-top:10px}
    .blog-pager{display:flex;justify-content:space-between;padding:16px}.status-msg-wrap{padding:14px}
    @media(max-width:640px){.sc-headin{align-items:flex-start}.sc-nav{width:100%;gap:3px}.sc-nav a{padding:7px 9px;font-size:14px}.sc-main{padding-top:16px}.sc-hero{border-radius:17px}}


/* Tools page — all selectors are scoped to .sc-page to avoid theme collisions */
.sc-page{max-width:980px;margin:0 auto;color:#182338;line-height:1.8}
.sc-page .sc-tools-hero{background:linear-gradient(130deg,#102b50,#176b87);color:#fff;padding:28px;border-radius:22px;margin:16px 0 24px}
.sc-page .sc-tools-hero h1{font-size:clamp(26px,5vw,38px);margin:0 0 8px}
.sc-page .sc-tools-hero p{margin:0;color:#e4f1fa}
.sc-page .sc-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}
.sc-page .sc-tabs button{border:0;border-radius:12px;padding:11px 16px;background:#176b87;color:#fff;font-weight:700;cursor:pointer;font:inherit}
.sc-page .sc-tabs button[aria-selected=true]{background:#102b50}
.sc-page .sc-tool-card{border:1px solid #dce5ed;border-radius:18px;padding:20px;margin:14px 0;background:#fff;box-shadow:0 5px 20px #102b500d}
.sc-page .sc-tool-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px}
.sc-page .sc-field label{display:block;font-weight:650;margin-bottom:5px}
.sc-page .sc-field input{width:100%;box-sizing:border-box;padding:12px;border:1px solid #cbd5df;border-radius:10px;font:inherit}
.sc-page .sc-tool-result{background:#eef7f8;border:1px solid #c8e3e7;padding:14px;border-radius:12px;margin-top:14px}
.sc-page .sc-tool-result strong{font-size:24px;color:#10566e}
.sc-page .sc-muted{color:#5c6c7e;font-size:14px}
.sc-page .sc-tool[hidden]{display:none!important}
@media(max-width:640px){.sc-page .sc-tools-hero{padding:22px}.sc-page .sc-tool-card{padding:15px}}

.sc-skip{position:absolute;right:12px;top:-60px;background:#fff;color:#102b50;padding:10px 14px;border-radius:8px;z-index:1000}.sc-skip:focus{top:8px}
.sc-page .sc-field input,.sc-page .sc-field select{width:100%;box-sizing:border-box;padding:12px;border:1px solid #cbd5df;border-radius:10px;font:inherit;background:#fff;color:#182338}
.sc-page .sc-tabs button:focus-visible,.sc-page input:focus-visible,.sc-page select:focus-visible,.sc-nav a:focus-visible{outline:3px solid #e6a23c;outline-offset:2px}
.sc-page .sc-tabs button{min-height:44px}
